\begin{tikzpicture}[x=1.15cm,y=0.65cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{seriesBlue}{HTML}{268CFF}
\definecolor{seriesOrange}{HTML}{EF8B2C}
\draw[->,black,line width=0.5pt] (-3,0)--(2.7,0) node[right] {$x$};
\draw[->,black,line width=0.5pt] (0,-2.7)--(0,5.6) node[above] {$y$};
\draw[dashed,black,line width=0.4pt] (-3,-2)--(2.55,-2) node[right] {$y=-2$};
