\begin{tikzpicture}[x=1.2cm,y=0.75cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{seriesBlue}{HTML}{268CFF}
\definecolor{seriesOrange}{HTML}{EF8B2C}
\draw[->,black,line width=0.5pt] (-3,0)--(3.4,0) node[right] {$x$};
\draw[->,black,line width=0.5pt] (0,-2.7)--(0,5.4) node[above] {$y$};
\draw[dashed,black,line width=0.4pt] (-3,4)--(3.2,4) node[right] {$y=4$};
\draw[seriesBlue,line width=0.8pt,domain=-3:2.65,samples=100] plot (\x,{4-pow(2,\x)});
