\fill[black] ({ln(3)/ln(2)},1) circle (1.5pt) node[above right] {$(\log_2 3,1)$};
\fill[black] (2,0) circle (1.3pt) node[below left] {$(2,0)$};
\node[below] at (-2.45,0) {$y=0$};
